const clean = o => JSON.parse(JSON.stringify(o, (k, v) => k[0] === '_' ? undefined : v));
const invalidate = o => { for (const k in o) if (k[0] === '_') delete o[k]; };

/* ---------- history: add / delete / modify / reorder, grouped in transactions ---------- */
